// GENERATED by scripts/sync-shared.mjs from hotel-clash-api/engine — do not edit here.
import { nextRandom, seedFrom } from './math.js';
import { INITIAL_CAMPAIGNS, INITIAL_COMPETITORS } from './data.js';

export const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));

export function seasonFor(day) {
  const d = day % 360;
  if (d < 90) return 'spring';
  if (d < 180) return 'summer';
  if (d < 270) return 'autumn';
  return 'winter';
}

/** Fresh game. Everything that affects the simulation lives in this object. */
export function createInitialState({ seed, hotelName = 'My Hotel', hotelType = 'standard', t = 0 } = {}) {
  return {
    v: 1,
    rng: seedFrom(seed ?? 'hotelclash'),
    nextId: 1,
    hotelName: String(hotelName).slice(0, 80),
    hotelType: String(hotelType).slice(0, 40),
    day: 1,
    season: seasonFor(1),
    money: 50000,
    credits: 0,
    reputation: 3,
    // A new hotel makes a small profit when full (~+$45/day, ~+$100 with
    // smart prices). It used to lose $185/day while 100% booked, which
    // pushed new players into firing staff and a debt spiral.
    rooms: [1, 2, 3, 4].map((id) => ({ id, type: 'Standard', price: 80, occupied: false, quality: 2, guest: null })),
    staff: [{ id: 1, name: 'Jane', role: 'Receptionist', salary: 150, skill: 2, happiness: 5 }],
    facilities: [{ id: 1, name: 'Lobby', level: 1, upkeep: 30 }],
    land: { plots: 1, paid: 0 },
    guests: [],
    competitors: INITIAL_COMPETITORS.map((c) => ({ ...c, facilities: [...c.facilities] })),
    marketShare: 0,
    totalGuestsServed: 0,
    marketData: [{ day: 0, share: 0, reputation: 3 }],
    hotelLevel: 1,
    marketingCampaigns: INITIAL_CAMPAIGNS.map((c) => ({ ...c })),
    insurance: 'none', // see INSURANCE_PLANS
    policies: { petFriendly: false, earlyCheckin: false, lateCheckout: false, freeCancellation: false, breakfastIncluded: false },
    achievements: [], // unlocked ids
    claimedRewards: [], // one-time social rewards
    appliedGrants: [], // server credit-transaction ids already added (purchases, rewards)
    challenge: null,
    away: null, // unclaimed away earnings: { ms, amount }
    stats: { lastDayRevenue: 0, maintenanceToday: 0 },
    events: { lastEventDay: 0, recent: [], counts: {}, lastDay: {}, seen: 0, last: {} },
    clock: { lastT: t, lastTickT: 0, wheelDate: '', wheelSpins: 0, ads: {}, visitDate: '', visited: [] },
  };
}

const num = (v, d = 0) => (Number.isFinite(Number(v)) ? Number(v) : d);
const str = (v, d, max = 80) => (typeof v === 'string' && v ? v.slice(0, max) : d);
const list = (v, max) => (Array.isArray(v) ? v.slice(0, max) : []);

/**
 * Convert a pre-engine game state (the old client-only `hotelClashGameState`)
 * into an engine state. Values are sanitised and capped by `limits`, because
 * this data was never verified by the server.
 */
export function stateFromLegacy(old, { seed, t = 0, hotelName, hotelType, achievements = [], limits = {} } = {}) {
  const S = createInitialState({ seed, hotelName, hotelType, t });
  if (!old || typeof old !== 'object') return S;
  const maxMoney = limits.maxMoney ?? 2_000_000;
  const maxCredits = limits.maxCredits ?? 0;

  S.day = clamp(Math.floor(num(old.day, 1)), 1, 100000);
  S.season = seasonFor(S.day);
  S.money = clamp(num(old.money, 100000), -1_000_000, maxMoney);
  S.credits = clamp(num(old.credits, 0), 0, maxCredits);
  S.reputation = clamp(num(old.reputation, 3), 1, 5);
  S.marketShare = clamp(num(old.marketShare, 0), 0, 95);
  S.hotelLevel = clamp(Math.floor(num(old.hotelLevel, 1)), 1, 5);
  S.totalGuestsServed = Math.max(0, Math.floor(num(old.totalGuestsServed, 0)));

  S.rooms = list(old.rooms, 500).map((r, i) => ({
    id: Math.floor(num(r && r.id, i + 1)),
    type: str(r && r.type, 'Standard', 40),
    price: clamp(Math.round(num(r && r.price, 80)), 1, 100000),
    quality: clamp(num(r && r.quality, 1), 1, 5),
    occupied: false,
    guest: null,
  }));
  S.staff = list(old.staff, 500).map((e, i) => ({
    id: Math.floor(num(e && e.id, i + 1)),
    name: str(e && e.name, 'Staff', 40),
    role: str(e && e.role, 'Receptionist', 40),
    salary: clamp(num(e && e.salary, 200), 0, 100000),
    skill: clamp(num(e && e.skill, 1), 0, 10),
    happiness: clamp(num(e && e.happiness, 3), 1, 5),
  }));
  const facilities = list(old.facilities, 200).map((f, i) => ({
    id: Math.floor(num(f && f.id, i + 1)),
    name: str(f && f.name, 'Lobby', 60),
    level: clamp(Math.floor(num(f && f.level, 1)), 1, 5),
    upkeep: clamp(num(f && f.upkeep, 70), 0, 1_000_000),
  }));
  if (facilities.length) S.facilities = facilities;
  // Guests are not imported: rooms start empty and fill up on the next day.
  if (Array.isArray(old.competitors) && old.competitors.length) {
    S.competitors = S.competitors.map((c) => {
      const o = old.competitors.find((x) => x && x.id === c.id);
      if (!o) return c;
      return {
        ...c,
        reputation: clamp(num(o.reputation, c.reputation), 1, 5),
        occupancyRate: clamp(num(o.occupancyRate, c.occupancyRate), 0.3, 0.95),
        avgRoomPrice: clamp(num(o.avgRoomPrice, c.avgRoomPrice), 40, 100000),
        facilities: list(o.facilities, 40).filter((x) => typeof x === 'string'),
      };
    });
  }
  if (old.policies && typeof old.policies === 'object') {
    for (const k of Object.keys(S.policies)) S.policies[k] = old.policies[k] === true;
  }
  S.claimedRewards = list(old.claimedRewards, 50).filter((x) => typeof x === 'string');
  S.achievements = list(achievements, 50).filter((x) => typeof x === 'string');
  S.marketData = list(old.marketData, 365)
    .filter((d) => d && Number.isFinite(Number(d.day)))
    .map((d) => ({ day: num(d.day), share: num(d.share), reputation: num(d.reputation, 3) }));
  if (!S.marketData.length) S.marketData = [{ day: 0, share: 0, reputation: S.reputation }];
  const maxId = Math.max(0, ...S.rooms.map((r) => r.id), ...S.staff.map((e) => e.id), ...S.facilities.map((f) => f.id));
  S.nextId = maxId + 1;
  return S;
}

/**
 * Per-action context: random numbers, effect collection and money helpers.
 * Effects are UI-only side outputs (notifications, modals, confetti) and are
 * never part of the state.
 */
export function makeContext(S, t) {
  const effects = [];
  const G = {
    S,
    t,
    effects,
    rand: () => nextRandom(S),
    emit: (effect) => effects.push(effect),
    notify: (message, isSpecial = false, type = 'general') => effects.push({ kind: 'notify', message, isSpecial, type }),
    newId: (prefix = '') => `${prefix}${S.nextId++}`,
    spendingPower: () => S.money + S.credits,
    /** Pay from money first, then premium credits. Returns false if unaffordable. */
    pay: (amount) => {
      if (G.spendingPower() < amount) return false;
      if (S.money >= amount) S.money -= amount;
      else {
        S.credits -= amount - S.money;
        S.money = 0;
      }
      return true;
    },
    setRooms: (fn) => {
      S.rooms = fn(S.rooms);
    },
    setGuests: (fn) => {
      S.guests = fn(S.guests);
    },
    setStaff: (fn) => {
      S.staff = fn(S.staff);
    },
    setFacilities: (fn) => {
      S.facilities = fn(S.facilities);
    },
    addReputation: (delta) => {
      S.reputation = clamp(S.reputation + delta, 1, 5);
    },
    /** Remove guests whose rooms were vacated, keeping rooms and guests consistent. */
    vacateRooms: (roomIds) => {
      const ids = new Set(roomIds);
      if (!ids.size) return;
      S.rooms = S.rooms.map((r) => (ids.has(r.id) ? { ...r, occupied: false, guest: null } : r));
      S.guests = S.guests.filter((g) => !ids.has(g.roomId));
    },
    vacateAll: () => {
      S.rooms = S.rooms.map((r) => ({ ...r, occupied: false, guest: null }));
      S.guests = [];
    },
  };
  return G;
}
